def ktables():
    j = table(["#", "王", "在位（主前，约）", "评价", "要点", "经文"], [[str(i+1), f"<b>{n}</b>", d, (c, {"g": "善", "r": "恶", "m": "善（不完全）"}[c]), t, r] for i, (n, d, c, t, r) in enumerate(JUDAH)])
    i_ = table(["王朝", "王", "在位（主前，约）", "评价", "要点"], [[dy, f"<b>{n}</b>", d, ("r", "恶"), t] for dy, n, d, t in ISRAEL])
    return ('<div class="legend"><span><i style="background:var(--green)"></i>行耶和华眼中看为正的事</span><span><i style="background:var(--red)"></i>行耶和华眼中看为恶的事</span><span><i style="background:var(--gold)"></i>善而不完全</span></div>'
            + '<details class="more" open><summary>🦁 南国犹大：20 位君王（含女王亚他利雅），一个王朝——大卫家</summary>' + j + '</details>'
            + '<details class="more"><summary>🐂 北国以色列：19 位君王，9 个王朝，全部被评为“恶”</summary>' + i_ + '</details>'
            + mnem("亚约约亚，乌约希约", "犹大八善王：亚撒·约沙法·约阿施·亚玛谢｜乌西雅·约坦·希西家·约西亚（★希西家、约西亚为最佳）")
            + mnem("耶巴心暗耶，沙米比何", "北国九王朝开创者：耶罗波安·巴沙·心利·暗利·耶户｜沙龙·米拿现·比加·何细亚"))
